var response = await client.DashboardReports.GetDashboardReportQuickAsync(
    new Dictionary<string, object?> { ["duration"] = "last_12_months", ["kpis"] = "total_sales,aov", ["entity_name"] = "product" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var period = (IReadOnlyDictionary<string, object?>)body["period"]!;
Console.WriteLine($"{period["start_date"]} {period["end_date"]} {period["currency"]}");
foreach (var kpi in ((IReadOnlyList<object?>)body["kpis"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{kpi["key"]} {kpi["value"]} {kpi["change_percent"]} {kpi["direction"]}");
var orders = (IReadOnlyDictionary<string, object?>)body["orders"]!;
Console.WriteLine($"{orders["count"]} {orders["pending"]} {orders["cancelled"]}");

